function closeRoundSimulation(round){delete roundSimulations[round];renderFixtures()}

function scoreForPlayer(score,home){return home?String(score):String(score).replace(/(\d+)\s*-\s*(\d+)/g,(_,a,b)=>b+'-'+a)}
