function partnerStats(name){return pairs.filter(x=>x.player.split(' / ').includes(name)).map(x=>({...x,partner:x.player.split(' / ').find(p=>p!==name)})).sort((a,b)=>b.matches-a.matches||b.rating-a.rating)}
